184	func (s *APIV1Service) clearAuthCookies(ctx context.Context) error {
185		// Clear refresh token cookie
186		refreshCookie := s.buildRefreshTokenCookie(ctx, "", time.Time{})
187		if err := SetResponseHeader(ctx, "Set-Cookie", refreshCookie); err != nil {
188			return errors.Wrap(err, "failed to set refresh cookie")
189		}
190	
191		return nil
192	}
